"""Real-link system test: ascendc-st-design self-closes via file I/O in TUI mode.

THE acceptance guard for M3 (§3.9) on the replaced test-design chain: the
ascendc-st-design skill must run in TUI mode WITHOUT the DevKit framework,
starting from a seeded 03_参数定义.yaml (what convert_to_param_def.py would
produce), running its deterministic script chain, and ending in a merge CSV that
parse_testcase_csv can parse.

Mirrors the deleted tests/st/test_testdesign_tui_selfclosure.py (old 3-skill
analyze→casedesign→casegen chain) — adapted to the single new skill. Spawns
agents DIRECTLY (no Stage / Runner / GraphExecutor) in a bare temp dir, exactly
as a human typing /<skill> would.

Backend: opencode（§4.2/§4.3 —— 原生发现同一棵 .claude/skills/<name>/SKILL.md
扁平树 + 首条消息 `/<skill>` 裸名投递，与 claude 的 slash 注入语义等价）。opencode
用自己的 opencode.json provider（不依赖 ANTHROPIC_*），本环境可真实跑；claude
后端缺 Anthropic 凭据时该测试诚实 skip（§3.7）。

Marked @pytest.mark.llm + @pytest.mark.heavy_llm: NOT in the default sweep
(§3.11 — real LLM full-flow, minute-scale); run explicitly via -m llm or by
name, on user decision.
"""

from __future__ import annotations

from pathlib import Path

import pytest

from tests.st._dual_backend import make_backend, require_live_opencode

_SCRIPTS = Path(__file__).resolve().parent.parent.parent / ".claude" / "skills" / "ascendc-st-design" / "scripts"


_MAX_ATTEMPTS = 3
_SKILL = "ascendc-st-design"


def _spawn(work_dir: Path, slash_skill: str, instruction: str):
    """Spawn a generator agent the way a TUI user would: first message leads with
    the /<skill> bare slash command, then a short instruction. No
    State, no Stage — only the files already in work_dir are available."""
    prompt = f"/{slash_skill}\n\n{instruction}"
    # 脚本链 6 步 + 自验证是分钟级真实工作：默认 message_timeout=180s 会在 agent
    # 产出合并 CSV 后（写总结报告时）被硬墙 abort，导致 spawn 抛异常、测试看不到
    # 已落盘的产物。给足 360s 让 agent 自然完成。
    backend = make_backend("opencode", work_dir.parent,
                           message_timeout=360.0)
    backend.spawn(
        "ascendc-design-generator", prompt, {},
        skills=[slash_skill], primary_skill=slash_skill,
        working_dir=work_dir, stage_name="tui",
    )


def _seed_param_def(d: Path) -> None:
    """Seed the step-3 input (03_参数定义.yaml) exactly as convert_to_param_def.py
    would produce it for a simple add operator (aplus)."""
    yaml_text = """# Generated by convert_to_param_def.py
# Sources: requirement.json, design_spec.json
aclnn_name: aclnnAdd

parameters:
  - name: x
    type: aclTensor
    required: true
    io_type: input
    format: ["ND"]
    dimensions: [1, 2, 3, 4]
    dtype_with_ranges:
      - dtype: bfloat16
        value_range: [-1, 1]
      - dtype: float32
        value_range: [-1, 1]
  - name: y
    type: aclTensor
    required: true
    io_type: input
    format: ["ND"]
    dimensions: [1, 2, 3, 4]
    dtype_with_ranges:
      - dtype: bfloat16
        value_range: [-1, 1]
      - dtype: float32
        value_range: [-1, 1]
  - name: z
    type: aclTensor
    required: true
    io_type: output
    format: ["ND"]
    dimensions: [1, 2, 3, 4]
    dtype_with_ranges:
      - dtype: bfloat16
      - dtype: float32
"""
    d.mkdir(parents=True, exist_ok=True)
    (d / "design" / "03_参数定义.yaml").parent.mkdir(parents=True, exist_ok=True)
    (d / "design" / "03_参数定义.yaml").write_text(yaml_text, encoding="utf-8")


def _parseable_cases(wd: Path) -> list | None:
    """Scan wd recursively for a merge CSV parseable by the adapter."""
    from ascendc_devkit.adapters.testdesign import parse_testcase_csv
    csvs = list(wd.rglob("*测试用例*.csv")) or list(wd.rglob("*.csv"))
    for c in csvs:
        try:
            cases = parse_testcase_csv(c)
        except (ValueError, OSError):
            continue
        if cases:
            return cases
    return None


@pytest.mark.llm
@pytest.mark.heavy_llm
def test_skill_self_closes_via_scripts_to_parseable_csv(tmp_path):
    """§3.9 M3 守护：ascendc-st-design 在 TUI 模式（无框架）下，从 seeded
    design/03_参数定义.yaml 出发，跑完确定性脚本链（step 3-10），产出
    parse_testcase_csv 能解析的合并 CSV。

    这是被删的 test_testdesign_tui_selfclosure heavy_llm 守卫在新单 skill 上的
    等价——旧守卫验证三步 LLM 链文件接力自闭环；新守卫验证单 skill 的脚本链
    自闭环（§2.1 即插即用：skill 取出后能独立产出完整产物）。"""
    require_live_opencode()

    for attempt in range(_MAX_ATTEMPTS):
        wd = tmp_path / f"ws_{attempt}"
        wd.mkdir(parents=True, exist_ok=True)
        _seed_param_def(wd)
        _spawn(
            wd, _SKILL,
            "通路验证测试。按 ascendc-st-design 工作流从 step 3 开始：从当前工作"
            "目录读取 design/03_参数定义.yaml，依次运行该 skill 的确定性脚本"
            "（generate_test_factors.py → generate_implicit_constraints.py → "
            "generate_solver_config.py → generate_factor_values.py → "
            "generate_test_cases.py 生成 L0/L1/L2 → merge_test_cases.py 合并），"
            "把中间产物写进 ./design/，用例写进 ./testcases/，合并 CSV 写到当前"
            "工作目录。用少量因子/参数即可，目标是跑通脚本链并产出可解析的合并"
            "CSV。产出合并 CSV 后立即停止，不要再做额外验证或总结。")
        cases = _parseable_cases(wd)
        if cases:
            return  # self-closed: script chain produced a parseable merge CSV
    pytest.fail(
        "ascendc-st-design did not self-close via its script chain in TUI mode: "
        f"no parseable merge CSV after {_MAX_ATTEMPTS} attempts (§3.9/M3 regression: "
        "the skill must run standalone from a seeded 03_参数定义.yaml to a parseable "
        "acceptance-case CSV, without the DevKit framework)")
